      "FCF Yield": f("fcfYield") * 0.3166,
      "Book-to-Market": f("bookToMarket") * 8.94,
      "Size (TEV)": Math.log(Math.max(f("tev"), 1e-3)) * -3.87,
      "ROA": f("roa") * 0.1523,
      "EBITDA Margin": f("ebitdaMargin") * 0.0621,
      "Asset Growth": form.assetGrowth === "redflag" ? -10.76 : 0,
      "Price Range": f("priceRange") * -0.0518,
      "1M Momentum": f("momentum1m") * 0.0733,
      "3M Momentum": f("momentum3m") * -0.0845,
      "6M Momentum": f("momentum6m") * 0.0912,
      "Interest Rates": form.interestRates === "rising" ? -10.14 : 0,
      "Market Return": f("marketReturn") * 0.0452
