    const assetsInPlace = nopatVal / k;
    const pvgo = selectedTV !== null ? Math.max(0, selectedTV - assetsInPlace) : 0;
    const pvgoPct = selectedTV && selectedTV > 0 ? pvgo / selectedTV * 100 : 0;
    const marketCap = price * shares;
    const firmValue = marketCap + netDebt;
    const fcfs = [nopat1, nopat2, nopat3, nopat4, nopat5].map((n2, i) => {
      const inv = n2 * invFrac;
      return n2 - inv;
    });
    const allFCFs = [...fcfs];
    for (let i = 5; i < 20; i++) {
      const prev = allFCFs[i - 1];
      allFCFs.push(prev * (1 + gFrac * 0.8));
    }
    let impliedCAP = null;
    for (let T = 1; T <= 20; T++) {
      let npv = 0;
      for (let t = 0; t < T; t++) {
        npv += allFCFs[t] / Math.pow(1 + k, t + 1);
      }
      const nopatAtT = allFCFs[T - 1] / (1 - invFrac) || nopatVal;
      let tvAtT;
      if (termModel === "perpetuity") tvAtT = nopatAtT / k;
      else if (termModel === "gordon") tvAtT = k > tg ? nopatAtT * (1 - invFrac) / (k - tg) : nopatAtT / k;
      else if (termModel === "vdm") tvAtT = k > tg && roiicFrac > 0 ? nopatAtT * (1 - tg / roiicFrac) / (k - tg) : nopatAtT / k;
      else {
        const perpT = nopatAtT / k;
        const vdmT = k > tg && roiicFrac > 0 ? nopatAtT * (1 - tg / roiicFrac) / (k - tg) : perpT;
        const num2 = (vdmT - perpT) * (1 - f) * (k - tg);
        const den2 = 1 + k - (1 - f) * (1 + tg);
        tvAtT = den2 > 0 ? perpT + num2 / den2 : perpT;
      }
      npv += tvAtT / Math.pow(1 + k, T);
      if (npv >= firmValue && impliedCAP === null) impliedCAP = T;
    }
    if (!impliedCAP) impliedCAP = ">20";
